examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    Box {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .combinedClickable(
                    onClick = {},
                    onLongClickLabel = {{menuLabel}},
                    onLongClick = { menu = true },
                )
                .padding(MonarchTheme.spacing.space4),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        ) {
            MonarchButton(text = {{file}}, onClick = { menu = true }, variant = MonarchButtonVariant.Ghost)
            MonarchText(text = "Long press the file for its actions.", style = MonarchTextStyle.Caption)
        }
        MonarchMenu(expanded = menu, onDismissRequest = { menu = false }) {
            MonarchMenuItem(
                text = {{items.0.label}},
                onClick = { last = {{items.0.label}}; menu = false },
                shortcut = {{items.0.shortcut}},
                leadingIcon = { MonarchIcon(SampleIcons.Pencil, contentDescription = null) },
            )
            MonarchMenuItem(
                text = {{items.1.label}},
                onClick = { last = {{items.1.label}}; menu = false },
            )
            MonarchMenuDivider()
            MonarchMenuItem(
                text = {{items.2.label}},
                onClick = { last = {{items.2.label}}; menu = false },
                destructive = true,
                leadingIcon = { MonarchIcon(SampleIcons.Trash, contentDescription = null) },
            )
        }
    }
    // The menu opens over the line below its anchor: the space keeps "Last action" visible under it.
    Spacer(Modifier.height(150.dp))
    MonarchText(text = "Last action: $last", style = MonarchTextStyle.Caption)
}

